create type user_role as enum ('owner','admin','mandor');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role user_role not null default 'mandor', created_at timestamptz default now());
create table plantations (id bigint generated by default as identity primary key, name text not null, location text, area_ha numeric(10,2) not null check(area_ha>=0), tree_count integer default 0, planting_year integer, status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz default now());
create table harvests (id bigint generated by default as identity primary key, harvest_date date not null, plantation_id bigint not null references plantations(id), weight_kg numeric(12,2) not null check(weight_kg>0), price_per_kg numeric(12,2) not null check(price_per_kg>=0), unloading_cost numeric(14,2) not null default 0, pks_destination text, notes text, created_by uuid references profiles(id), created_at timestamptz default now());
create table expense_categories (id bigint generated by default as identity primary key, name text unique not null, active boolean default true);
insert into expense_categories(name) values ('Pupuk'),('Herbisida/Racun'),('Upah panen'),('Upah pemupukan'),('Upah penyemprotan'),('Transportasi'),('BBM'),('Perbaikan/Perawatan'),('Alat & perlengkapan'),('Lainnya');
create table expenses (id bigint generated by default as identity primary key, expense_date date not null, plantation_id bigint not null references plantations(id), category_id bigint references expense_categories(id), amount numeric(14,2) not null check(amount>=0), payee text, notes text, created_by uuid references profiles(id), created_at timestamptz default now());
create table maintenance (id bigint generated by default as identity primary key, scheduled_date date not null, plantation_id bigint not null references plantations(id), activity_type text not null, status text not null default 'scheduled' check(status in ('scheduled','completed')), notes text, cost numeric(14,2) default 0, created_by uuid references profiles(id), created_at timestamptz default now());
create view harvest_financials as select h.*, (weight_kg*price_per_kg) gross_revenue, (weight_kg*price_per_kg-unloading_cost) net_revenue from harvests h;
